#!/usr/bin/env python3
"""Collect Friend-Message: 1 commits from all six conversation branches."""
import subprocess, json, re
from collections import Counter

REPO = "/tmp/ross-main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
SUBJ = re.compile(r"^friend:\s+(\w+)\s*\|\s*(S\d+/E\d+)\s*$")

def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args),
                          capture_output=True, text=True, check=True).stdout

def parse(sha, date, subject, body):
    m = SUBJ.match(subject.strip())
    if not m:
        return None
    lines = body.split("\n")
    # header block = lines until first blank line after subject
    hdr = {}
    idx_reply = None
    for i, l in enumerate(lines):
        if l.strip() == "":
            break
        if l.startswith("Friend-Message:") and l.split(":", 1)[1].strip() == "1":
            hdr["msg"] = True
        elif l.startswith("Speaker:"):
            hdr["speaker"] = l.split(":", 1)[1].strip()
        elif l.startswith("Episode:"):
            hdr["episode"] = l.split(":", 1)[1].strip()
        elif l.startswith("Reply-To:"):
            hdr["reply_to"] = l.split(":", 1)[1].strip()
            idx_reply = i
    if not hdr.get("msg") or "speaker" not in hdr or "episode" not in hdr or idx_reply is None:
        return None
    j = idx_reply + 1
    while j < len(lines) and lines[j].strip() == "":
        j += 1
    text = "\n".join(lines[j:]).strip("\n")
    return dict(sha=sha, branch="friend/" + hdr["speaker"].lower() if False else None,
                date=date, speaker=hdr["speaker"], episode=hdr["episode"],
                reply_to=hdr["reply_to"], text=text, subject=subject)

msgs = []
for key in BRANCHES:
    br = "friend/" + key
    out = git("log", "--reverse", "--format=%H%x00%cI%x00%s%x00%B%x01", "origin/" + br)
    for rec in out.split("\x01"):
        if not rec.strip():
            continue
        parts = rec.split("\x00", 3)
        if len(parts) < 4:
            continue
        sha, cdate, subject, body = parts
        rec_msg = parse(sha, cdate, subject, body)
        if rec_msg:
            rec_msg["branch"] = br
            msgs.append(rec_msg)

msgs.sort(key=lambda m: (m["date"], m["sha"]))
json.dump(msgs, open("/tmp/msgs.json", "w"), indent=1)
print("total messages:", len(msgs))
c = Counter(m["episode"] for m in msgs)
for ep in sorted(c, key=lambda e: (e is None, e)):
    print(ep, c[ep])

