#!/usr/bin/env python3
"""Ross's editorial pass: file every unfiled Friend-Message into the episode files."""
import subprocess, re, os, glob, datetime, sys

MAIN = "/tmp/ross-main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
SUBJ = re.compile(r"^friend:\s+(\w+)\s*\|\s*(S\d+/E\d+)\s*$")
SKIP_PREFIX = ("Correction", "Late-Arrival", "Episode-Coordination", "Note:", "Bookkeeping")

def git(*args):
    return subprocess.run(["git", "-C", MAIN] + list(args),
                          capture_output=True, text=True, check=True).stdout

def collect():
    msgs = []
    for key in BRANCHES:
        br = "friend/" + key
        out = git("log", "--reverse", "--format=%H%x00%cI%x00%s%x00%B%x01", "origin/" + br)
        for rec in out.split("\x01"):
            if not rec.strip():
                continue
            parts = rec.split("\x00", 3)
            if len(parts) < 4:
                continue
            sha, cdate, subject, body = [p.strip() for p in parts]
            if not SUBJ.match(subject):
                continue
            lines = body.split("\n")
            if lines and lines[0].strip() == subject:
                lines = lines[1:]
            while lines and lines[0].strip() == "":
                lines = lines[1:]
            hdr, idx_reply = {}, None
            for i, l in enumerate(lines):
                if l.strip() == "":
                    break
                if l.startswith("Friend-Message:"):
                    hdr["msg"] = l.split(":", 1)[1].strip()
                elif l.startswith("Speaker:"):
                    hdr["speaker"] = l.split(":", 1)[1].strip()
                elif l.startswith("Episode:"):
                    hdr["episode"] = l.split(":", 1)[1].strip()
                elif l.startswith("Reply-To:"):
                    hdr["reply_to"] = l.split(":", 1)[1].strip()
                    idx_reply = i
            if hdr.get("msg") != "1" or "speaker" not in hdr or "episode" not in hdr or idx_reply is None:
                continue
            j = idx_reply + 1
            while j < len(lines) and lines[j].strip() == "":
                j += 1
            text = "\n".join(lines[j:]).strip("\n")
            msgs.append(dict(sha=sha, branch=br, date=cdate, speaker=hdr["speaker"],
                             episode=hdr["episode"], reply_to=hdr["reply_to"], text=text))
    msgs.sort(key=lambda m: (m["date"], m["sha"]))
    return msgs

def ts(iso):
    dt = datetime.datetime.fromisoformat(iso.replace("Z", "+00:00"))
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def entry(m):
    return ("**%s** (%s)\n\nSource: %s @ %s\n\n%s" %
            (m["speaker"], ts(m["date"]), m["branch"], m["sha"], m["text"]))

def main():
    git("fetch", "origin")
    msgs = collect()
    filed, texts = set(), set()
    for path in glob.glob(os.path.join(MAIN, "S*", "E*.md")):
        content = open(path).read()
        for m in re.finditer(r"Source:\s+friend/(\w+)\s+@\s+([0-9a-f]{40})", content):
            filed.add(m.group(2))
        for m in re.finditer(
                r"^\*\*(\w+)\*\* \([^)]+\)\n\nSource: friend/\w+ @ [0-9a-f]{40}\n\n(.*?)(?=\n\n\*\*|\n\n<!--|\Z)",
                content, re.S | re.M):
            texts.add(m.group(2).strip())
    new = []
    for m in msgs:
        if m["sha"] in filed:
            continue
        if m["text"].strip() in texts:
            continue
        if m["text"].lstrip().startswith(SKIP_PREFIX):
            print("skip meta:", m["sha"], m["episode"], m["text"][:60])
            continue
        new.append(m)
    by_ep = {}
    for m in new:
        by_ep.setdefault(m["episode"], []).append(m)
    for ep in sorted(by_ep):
        path = os.path.join(MAIN, ep.replace("/", os.sep) + ".md")
        content = open(path).read()
        idx = content.rfind("\n<!--")
        head = content[:idx] if idx != -1 else content
        tail = content[idx:] if idx != -1 else ""
        head = head.rstrip("\n")
        for m in by_ep[ep]:
            head += "\n\n" + entry(m)
        open(path, "w").write(head + "\n" + tail)
        print("filed", len(by_ep[ep]), "into", ep)
    json_out = [{"sha": m["sha"], "episode": m["episode"], "speaker": m["speaker"],
                 "date": m["date"], "branch": m["branch"]} for m in new]
    import json
    json.dump(json_out, open("/tmp/filed_now.json", "w"), indent=1)

main()
